#!/usr/bin/env python3
from pathlib import Path
import re

P = Path('race-sports/live.html')


def replace_once(s, old, new, label):
    if old not in s:
        raise SystemExit('MARKET_EDGE_UI_PATCH_MISSING:' + label)
    return s.replace(old, new, 1)


def main():
    s = P.read_text(encoding='utf-8')
    if 'function marketDecision(e)' in s and 'UPSET WATCH' in s:
        print('MARKET_EDGE_UI_PATCH=ALREADY_APPLIED')
        return

    s = replace_once(
        s,
        '.aiPick b{color:#caffdf;font-size:11px}',
        '.aiPick b{color:#caffdf;font-size:11px}.upsetPick{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:9px 10px;border-bottom:1px solid #5c4220;background:#291d0c;font-size:10px}.upsetPick small{color:#d7b36f}.upsetPick b{color:#ffd276;font-size:11px}.upsetPick.value{border-color:#1d4938;background:#0e271d}.upsetPick.value b{color:#73f1b0}.upsetTag{display:inline-block;margin-left:5px;padding:2px 6px;border-radius:999px;border:1px solid #9a6d28;color:#ffd276;background:#33240d;font-size:7px;font-weight:950}.primaryTag{display:inline-block;margin-left:5px;padding:2px 6px;border-radius:999px;border:1px solid #2f7a58;color:#73f1b0;background:#123324;font-size:7px;font-weight:950}',
        'css'
    )
    s = s.replace('<button data-view="VALUE">VALUE</button>', '<button data-view="VALUE">EDGE</button>', 1)

    anchor = "function aiTop(e){return (e.outcomes||[]).filter(o=>Number(o.model_p)>0).sort((a,b)=>Number(b.model_p)-Number(a.model_p))[0]||null}\n"
    helpers = r'''function marketDecision(e){return e?.market_decision&&typeof e.market_decision==='object'?e.market_decision:{}}
function marketRow(e,key){return (marketDecision(e).market||[]).find(x=>x.key===key)||null}
function signalPick(e){const d=marketDecision(e);return d.upset_pick||d.value_pick||d.primary_pick||null}
function signalBox(e){const d=marketDecision(e),p=signalPick(e);if(!p)return'';const upset=!!d.upset_pick&&p.key===d.upset_pick.key,type=upset?'UPSET':'VALUE',cls=upset?'':' value',edge=Number(p.edge||0),ev=Number(p.ev||0),mp=Number(p.market_p||0),ap=Number(p.model_p||0),od=Number(p.odds||0),name=outcomeLabel(e,p.key,p.name),grade=p.grade||'C',risk=p.risk||'NORMAL',q=d.odds_quality||'OFFICIAL';let verdict='';if(e.status==='FINAL'&&d.evaluation){const k=upset?'upset_pick_hit':'value_pick_hit',hit=d.evaluation[k];if(typeof hit==='boolean')verdict=`<span class="aiVerdict ${hit?'hit':'miss'}">${hit?'✓ 적중':'✕ 미적중'}</span>`}return `<div class="upsetPick${cls}"><span><small>${upset?'🔥 UPSET WATCH · 시장이 과소평가한 역배':'MARKET EDGE · 승률 1위가 아닌 가치 우선'} · ${esc(q)}</small><br><span class="aiCompare"><b>${esc(name)}</b><span class="upsetTag">${type} ${esc(grade)}</span>${verdict}</span></span><span><b>EDGE ${edge>=0?'+':''}${(edge*100).toFixed(1)}%p</b><br><small>AI ${(ap*100).toFixed(1)}% · 시장 ${(mp*100).toFixed(1)}% · ${od.toFixed(2)}배 · EV ${ev>=0?'+':''}${(ev*100).toFixed(1)}% · ${esc(risk)}</small></span></div>`}
'''
    s = replace_once(s, anchor, anchor + helpers, 'helpers')

    runners = r'''function runners(e){const fallback=probs(e),d=marketDecision(e),rows=Object.fromEntries((d.market||[]).map(x=>[x.key,x])),marketTop=(d.market_favorite?.key)||Object.entries(fallback).sort((a,b)=>b[1]-a[1])[0]?.[0],top=aiTop(e)?.key,upKey=d.upset_pick?.key,primaryKey=d.primary_pick?.key;if(!(e.outcomes||[]).length)return `<div class="empty"><b>출전자 상세 수집 대기</b>공식 일정은 확인됐고 세부 출전자 데이터는 아직 연결되지 않았습니다.</div>`;return `<div class="gridHead"><span>출전</span><span>AI확률</span><span>시장확률</span><span>배당</span></div>`+(e.outcomes||[]).map(o=>{const p=Number(o.model_p),r=rows[o.key],m=r?Number(r.market_p):fallback[o.key],dod=Number(o.odds),isTop=top===o.key,isUp=upKey===o.key,isPrimary=primaryKey===o.key,ev=r?Number(r.ev):null,tag=isUp?`<span class="upsetTag">역배 ${esc(r.grade||'C')}</span>`:isPrimary?`<span class="primaryTag">EDGE 추천</span>`:ev!==null&&ev>=.05?`<span class="evTag">EV +${(ev*100).toFixed(1)}%</span>`:'';return `<div class="runner ${isTop?'aiwin':''}"><span class="nm">${esc(o.name)}${isTop?`<span class="aiTag">AI승률 1위</span>`:''}${tag}${(!fresh(e)||!modelFresh(e))?`<span class="staleTag">지연</span>`:''}${o.final_rank?` · <span class="leader">${o.final_rank}위</span>`:''}${o.name_ko&&o.name_ko!==o.name?`<span class="runnerKo">${esc(o.name_ko)}</span>`:''}</span><span class="num model">${p>0?(p*100).toFixed(1)+'%':'—'}</span><span class="num market ${marketTop===o.key?'leader':''}">${m?(m*100).toFixed(1)+'%':'—'}</span><span class="num odds">${e.status==='FINAL'&&Number(o.final_odds)>0?Number(o.final_odds).toFixed(1):visibleOdds(o)?dod.toFixed(1):'—'}</span></div>`}).join('')}
'''
    s, n = re.subn(r'function runners\(e\)\{.*?\}\nfunction sportsTeamName', runners + 'function sportsTeamName', s, count=1, flags=re.S)
    if n != 1:
        raise SystemExit('MARKET_EDGE_UI_PATCH_MISSING:runners')

    sports_card = r'''function sportsCard(e){const st=statusText(e),off=['CANCELLED','POSTPONED','SUSPENDED'].includes(e.status),cls=!fresh(e)?'stale':e.status==='LIVE'?'live':e.status==='FINAL'?'final':off?'off':'',home=sportsTeamName(e,'home'),away=sportsTeamName(e,'away'),hs=e.result?.home_score??e.score?.home,as=e.result?.away_score??e.score?.away,score=(hs!==undefined&&hs!==null&&as!==undefined&&as!==null)?`${hs} : ${as}`:'VS',head=`<div class="head"><div class="time">${esc(displayStart(e))}</div><div><div class="league">${esc(e.competition||LABEL[e.sport]||e.sport)}</div><div class="meta">${esc(e.title||e.id)} · ${esc(e.provider||'-')}</div></div><div class="status ${cls}">${st}</div></div>`,match=`<div class="teamMatch"><div class="team"><small>HOME</small><b>${esc(home)}</b>${sportsTeamKo(e,'home')?`<span class="teamKo">${esc(sportsTeamKo(e,'home'))}</span>`:''}</div><div class="score">${esc(score)}</div><div class="team"><small>AWAY</small><b>${esc(away)}</b>${sportsTeamKo(e,'away')?`<span class="teamKo">${esc(sportsTeamKo(e,'away'))}</span>`:''}</div></div>`;let ai='';const t=aiTop(e),actual=sportsWinnerKey(e);if(t){const pred=t.key==='HOME'?home:t.key==='AWAY'?away:'무승부',pct=(Number(t.model_p)*100).toFixed(1);if(e.status==='FINAL'&&actual){const actualLabel=actual==='HOME'?home:actual==='AWAY'?away:'무승부',hit=t.key===actual;ai=`<div class="aiPick"><span><small>SPORTS AI · 순수 승률 1위</small><br><span class="aiCompare"><b>${esc(pred)} ${pct}%</b><span class="aiArrow">→</span><b class="aiActual">실제 ${esc(actualLabel)}</b><span class="aiVerdict ${hit?'hit':'miss'}">${hit?'✓ 적중':'✕ 미적중'}</span></span></span></div>`}else ai=`<div class="aiPick"><span><small>SPORTS AI · 순수 승률 1위 · 추천과 별개</small><br><b>${esc(pred)}</b></span><b>${pct}%</b></div>`}const outs=(e.outcomes||[]).length?runners(e):'';const visible=(e.outcomes||[]).filter(visibleOdds),provider=visible.find(o=>o.odds_provider)?.odds_provider||e.odds_provider||'',hasActionable=(e.outcomes||[]).some(preOdds),md=marketDecision(e),signal=md.primary_pick?`${md.primary_type} 추천 활성`:'시장 EDGE 대기',oddsMeta=visible.length?`<div class="sportsMeta">배당 · ${esc(provider||'출처표시')} · ${esc(signal)}</div>`:`<div class="sportsMeta">배당 · 원천 미제공</div>`;let foot;if(e.status==='FINAL')foot='종료 · 경기전 EDGE 추천 결과 비교';else if(off)foot='경기 상태 변경 · 추천 비활성';else if(md.primary_pick)foot=`${md.primary_type==='UPSET'?'역배 후보':'VALUE'} · 시장대비 과소평가 탐지`;else if(hasActionable)foot='배당은 있으나 기준 EDGE 미달 · NO BET';else foot='배당 원천 미제공/미확정';return `<article class="event ${fresh(e)?'':'stale'}">${head}${match}${oddsMeta}${ai}${signalBox(e)}${outs}<div class="foot"><span>${e.status==='FINAL'?'공식 결과':'공식 경기'}</span><span>${foot}</span></div></article>`}
'''
    s, n = re.subn(r'function sportsCard\(e\)\{.*?\}\n\nfunction card', sports_card + '\nfunction card', s, count=1, flags=re.S)
    if n != 1:
        raise SystemExit('MARKET_EDGE_UI_PATCH_MISSING:sportsCard')

    racing_card = r'''function card(e){if(domain==='SPORTS')return sportsCard(e);const st=statusText(e),cls=!fresh(e)?'stale':e.status==='LIVE'?'live':e.status==='FINAL'?'final':'';const shownTime=displayStart(e);const head=`<div class="head"><div class="time">${esc(shownTime)}</div><div><div class="league">${esc(e.competition||LABEL[e.sport]||e.sport)}</div><div class="meta">${esc(e.title||e.id)} · ${esc(e.provider||'-')}</div></div><div class="status ${cls}">${st}</div></div>`;const match=e.market_type==='THREE_WAY'?`<div class="bullMatch"><div class="side"><small>홍</small><b>${esc(e.left||'-')}</b></div><div>VS</div><div class="side"><small>청</small><b>${esc(e.right||'-')}</b></div></div>`:'';const hasOdds=fresh(e)&&(e.outcomes||[]).some(preOdds),md=marketDecision(e),foot=!fresh(e)?'직전 정상 스냅샷 유지 · 추천 비활성':!modelFresh(e)?'AI 지연 · 추천 비활성':e.status==='FINAL'?'종료 · 경기전 EDGE 추천 결과 비교':md.primary_pick?`${md.primary_type==='UPSET'?'역배 후보':'VALUE'} · 시장대비 과소평가 탐지`:hasOdds?'공식 배당 확보 · 기준 EDGE 미달이면 NO BET':'경기전 배당 공개 대기';return `<article class="event ${fresh(e)?'':'stale'}">${head}${resultBox(e)}${match}${aiBox(e)}${signalBox(e)}${runners(e)}<div class="foot"><span>${e.status==='FINAL'?'공식 결과':'공식 출전표'}</span><span>${foot}</span></div></article>`}
'''
    s, n = re.subn(r'function card\(e\)\{.*?\}\nfunction renderMetrics', racing_card + 'function renderMetrics', s, count=1, flags=re.S)
    if n != 1:
        raise SystemExit('MARKET_EDGE_UI_PATCH_MISSING:card')

    render = r'''function signalPanel(e,p,type){const edge=Number(p.edge||0),ev=Number(p.ev||0),ai=Number(p.model_p||0),mp=Number(p.market_p||0),od=Number(p.odds||0),title=type==='UPSET'?'🔥 UPSET WATCH':'MARKET VALUE';return `<div class="panel"><b>${title} · ${esc(displayStart(e))} · ${esc(e.title||e.id)} · ${esc(outcomeLabel(e,p.key,p.name))}</b><p>AI ${(ai*100).toFixed(1)}% · 시장 ${(mp*100).toFixed(1)}% · <b>EDGE ${edge>=0?'+':''}${(edge*100).toFixed(1)}%p</b></p><p>배당 ${od.toFixed(2)}배 · EV ${ev>=0?'+':''}${(ev*100).toFixed(1)}% · 등급 ${esc(p.grade||'C')} · 위험 ${esc(p.risk||'NORMAL')} · ${esc(marketDecision(e).odds_quality||'OFFICIAL')}</p></div>`}
function render(){renderMetrics();const a=scoped(),stale=a.filter(e=>!fresh(e)).length;notice.classList.toggle('warn',stale>0);notice.innerHTML=stale?`<b>${stale}경기 데이터 지연</b> · 지연 데이터에서는 MARKET EDGE 추천을 자동 차단합니다.`:`<b>AI 승률 1위는 추천과 다릅니다.</b> RACEIQ 추천은 배당의 시장확률과 AI확률 차이(EDGE)를 비교하고, 과소평가된 역배를 우선 탐지합니다.`;if(view==='TODAY'){content.innerHTML=`<div class="section"><h2>오늘 경기</h2><span>${a.length}경기</span></div>${a.length?a.map(card).join(''):`<div class="empty"><b>오늘 해당 종목 경기 없음</b>연결된 공식 경기만 표시합니다.</div>`}`;return}if(view==='VALUE'){const sig=a.filter(e=>fresh(e)&&e.status==='SCHEDULED'&&marketDecision(e).primary_pick),up=sig.filter(e=>marketDecision(e).upset_pick),val=sig.filter(e=>marketDecision(e).primary_type==='VALUE');content.innerHTML=`<div class="section"><h2>🔥 UPSET WATCH</h2><span>${up.length}건</span></div>${up.length?up.sort((a,b)=>Number(marketDecision(b).upset_pick.edge)-Number(marketDecision(a).upset_pick.edge)).map(e=>signalPanel(e,marketDecision(e).upset_pick,'UPSET')).join(''):`<div class="empty"><b>현재 검증된 역배 후보 없음</b>억지로 역배를 만들지 않습니다. AI확률이 시장확률보다 최소 +5%p 높고 EV +8% 이상인 역배만 표시합니다.</div>`}<div class="section"><h2>MARKET VALUE</h2><span>${val.length}건</span></div>${val.length?val.sort((a,b)=>Number(marketDecision(b).value_pick.edge)-Number(marketDecision(a).value_pick.edge)).map(e=>signalPanel(e,marketDecision(e).value_pick,'VALUE')).join(''):`<div class="empty"><b>추가 VALUE 없음</b>정배/역배와 무관하게 시장 대비 EDGE가 부족하면 NO BET입니다.</div>`}`;return}if(view==='ANALYSIS'){const odds=a.filter(e=>fresh(e)&&e.status==='SCHEDULED'&&(e.outcomes||[]).some(preOdds)).length,models=a.filter(e=>(e.outcomes||[]).some(o=>Number(o.model_p)>0)).length,up=a.filter(e=>marketDecision(e).upset_pick).length,val=a.filter(e=>marketDecision(e).value_pick).length;content.innerHTML=`<div class="section"><h2>분석 상태</h2></div><div class="panel"><div class="kv"><span>현재 경기</span><span>${a.length}경기</span></div><div class="kv"><span>사용가능 배당</span><span>${odds}경기</span></div><div class="kv"><span>AI확률 연결</span><span>${models}경기</span></div><div class="kv"><span>역배 후보</span><span>${up}건</span></div><div class="kv"><span>VALUE 후보</span><span>${val}건</span></div><div class="kv"><span>확정 결과</span><span>${a.filter(e=>e.status==='FINAL').length}경기</span></div><p>추천 순위는 순수 승률이 아니라 시장확률 대비 EDGE와 EV를 사용합니다. 기준 미달이면 정배도 추천하지 않습니다.</p></div>`;return}content.innerHTML=`<div class="section"><h2>설정</h2></div><div class="panel"><div class="kv"><span>자동수집</span><span>약 5분 주기</span></div><div class="kv"><span>화면갱신</span><span>10초</span></div><div class="kv"><span>AI 승률</span><span>순수 승리확률 · 추천과 분리</span></div><div class="kv"><span>MARKET EDGE</span><span>AI확률 - 배당 내재확률</span></div><div class="kv"><span>VALUE 기준</span><span>EDGE ≥ +3%p · EV ≥ +5%</span></div><div class="kv"><span>UPSET 기준</span><span>시장 1순위가 아닌 선택 · EDGE ≥ +5%p · EV ≥ +8%</span></div><div class="kv"><span>추천 우선순위</span><span>UPSET → VALUE → 기준 미달 NO BET</span></div><div class="kv"><span>안전장치</span><span>검증 모델 + 경기전 배당 + STALE 차단</span></div><div class="kv"><span>배당 출처</span><span>RACING 공식 · SPORTS 출처표시/다중북 구분</span></div></div>`}
'''
    s, n = re.subn(r'function render\(\)\{.*?\}\nasync function load', render + 'async function load', s, count=1, flags=re.S)
    if n != 1:
        raise SystemExit('MARKET_EDGE_UI_PATCH_MISSING:render')

    P.write_text(s, encoding='utf-8')
    print('MARKET_EDGE_UI_PATCH=PASS')


if __name__ == '__main__':
    main()
